function iso(d){d=D(d);if(isNaN(d))return '';return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function businessDT(dateValue,fallback){
  if(!dateValue)return fallback||null;
