function hasExactClockTime(v){
  v=String(v==null?'':v).trim();
  return /(?:T|\s)\d{1,2}:\d{2}(?::\d{2})?/.test(v)
}
function approvalTimeDisplay(v){
  if(!v)return '—';
  return hasExactClockTime(v)?fmtDT(v):fmtD(v)
