  // Export/print rendering never contains the full number at all.
  // This is intentionally independent of the on-screen MASK state.
  if(OUTPUT_PRIVACY_MODE){
    return '<span class="life-mobile life-mobile-output">'+esc(masked)+'</span>';
  }

  // System Manager has clicked "Unmask No.".
  if(!MASK){
    return '<span class="life-mobile life-mobile-open">'+full+'</span>';
  }

  // Very short values cannot preserve both first 3 and last 3 while masking.
  if(m.length<=6){
    return '<span class="life-mobile">'+full+'</span>';
  }

  // Screen view: masked by default, full value revealed only on hover.
  return ''+
    '<span class="life-mobile life-mobile-hover">'+
      '<span class="life-mobile-masked">'+esc(masked)+'</span>'+
      '<span class="life-mobile-full">'+full+'</span>'+
