  if(name){
    USERMAP[name]=nm||name;
    USERMAP[name.toLowerCase()]=nm||name;
    USER_CANON[name]=name;
    USER_CANON[name.toLowerCase()]=name;
  }
  if(username){
    USERMAP[username]=nm||username;
    USERMAP[username.toLowerCase()]=nm||username;
    USER_CANON[username]=name||username;
    USER_CANON[username.toLowerCase()]=name||username;
  }
}
function rememberEmployee(e){
  e=e||{};
  var empId=text(e.name),uid=text(e.user_id);
