}
function employeeForUser(u){
  u=text(u);
  if(!u)return null;
  var canon=canonicalUserRef(u);
  return EMP_BY_USER[canon]||EMP_BY_USER[canon.toLowerCase()]||EMP_BY_USER[u]||EMP_BY_USER[u.toLowerCase()]||null;
}
function userDesignation(u){
  var emp=employeeForUser(u);
