}
function cleanUser(u){u=text(u);if(!u)return '';var mapped=userMapValue(u);if(mapped)return mapped;return u.replace(/@.*$/,'').replace(/[._-]+/g,' ').replace(/\b\w/g,function(x){return x.toUpperCase()})}
function cleanEmp(e){e=text(e);return EMPMAP[e]?EMPMAP[e].employee_name:e}
