    HAS_NEXT=spref.length>end;
    CURRENT_TOTAL=clientFiltersActive(TYPE)?null:(TOTALS[TYPE]||0);
    DATA=spref.slice(start,end)
  }else if(clientFiltersActive(TYPE)){
    var pref=await fetchMatchingPrefix(TYPE,need);
    HAS_NEXT=pref.length>end;CURRENT_TOTAL=null;DATA=pref.slice(start,end)
