  (invoices||[]).forEach(function(invoice){
    (invoice.items||[]).forEach(function(item){
      var names=[item.item_code,item.item_name,item.description].join(' ').toLowerCase();
      if(!therapyType||names.indexOf(therapyType)<0)return;
      matched=true;
      var taxable=num(item.net_amount||item.base_net_amount||item.amount||item.base_amount);
      var gst=num(item.cgst_amount)+num(item.sgst_amount)+num(item.igst_amount)+num(item.cess_amount);
