            try{r.linkedPOs.push(await getDoc('Purchase Order',r.linkedPurchaseOrders[pi]))}catch(pe){void 0}
          }
        }
      }
    }
    r.hydrated=true;return r
  }catch(e){toast('Could not load full request: '+errText(e),'err');void 0;return r}
}

/* ---------- derived record helpers ---------- */
function apprAt(r,lvl){var ss=(r.stages||[]).concat(r.extraStages||[]);for(var i=0;i<ss.length;i++)if(ss[i]&&ss[i].lvl===lvl)return ss[i];return null}
function doneAt(r){if(r.status!=='Process Completed')return null;var ss=(r.stages||[]).concat(r.extraStages||[]);for(var i=ss.length-1;i>=0;i--){if(ss[i]&&ss[i].at)return ss[i].at}if(r.raw&&r.raw.process_completed_on)return r.raw.process_completed_on;if(r.type==='STK'&&r.raw&&r.raw.docstatus===1)return r.raw.modified||r.raw.creation||null;return null}
function tatH(r){var e=doneAt(r);return hrs(r.reqDT, e||TODAY)}
function pendLvl(r){var ss=(r.stages||[]).concat(r.extraStages||[]);for(var i=0;i<ss.length;i++)if(ss[i]&&ss[i].status==='Pending')return ss[i].lvl;return 0}
function allApprovers(r){return (r.stages||[]).concat(r.extraStages||[]).filter(function(s){return s.status==='Approved'}).map(function(s){return s.person}).filter(Boolean)}

/* =========================================================================
   COLUMN DEFINITIONS  — every cell carries two data points (line 1 + line 2)
   ========================================================================= */
function two(a,b,cls){return '<div class="l1'+(cls||'')+'">'+a+'</div><div class="l2'+(cls||'')+'">'+b+'</div>'}
function gIcon(g){return g==='Female'?'\uD83D\uDC69':(g==='Male'?'\uD83D\uDC68':'•')}

function stageCell(r,lvl){
  var s=apprAt(r,lvl);
  if(!s)return '<div class="l1" style="color:#95A39B">—</div><div class="l2">Not reached</div>';
  var who=esc(s.person||s.role||'');
  if(s.status==='Pending'){
    var start=prevAt(r,lvl),w=start?ageTxt(start,TODAY):'—',br=start?hrs(start,TODAY)>168:false;
    return '<div class="l1 pend-i">⏳ Pending</div><div class="l2"><b'+(br?' class="aged"':'')+'>'+(start?'waiting '+w:'awaiting action')+'</b> · '+who+'</div>';
  }
  if(s.status==='Rejected')return '<div class="l1 rej-i">✖ '+who+'</div><div class="l2">'+(s.at?approvalTimeDisplay(s.at)+' · '+approvalDuration(prevAt(r,lvl),s.at):'time not recorded')+'</div>';
  return '<div class="l1 ok-i">✔ '+who+'</div><div class="l2">'+(s.at?approvalTimeDisplay(s.at)+' · <b>'+approvalDuration(prevAt(r,lvl),s.at)+'</b>':'approved · time not recorded')+'</div>';
}
function prevAt(r,lvl){if(lvl===1)return r.reqDT;var p=apprAt(r,lvl-1);return (p&&p.at)?p.at:r.reqDT}

function stockWorkflowSummary(r){
  if(!r||r.type!=='STK')return {title:'—',sub:'—',actor:'',at:''};

  var state=text(r.workflowState||r.priority||r.sourceStatus,'Pending');

  if(r.stockSource==='Material Request'){
    return {title:state,sub:'Material Request status · no 3-level approval chain',actor:'',at:''};
  }

  var stages=(r.stages||[]).filter(function(x){
    return x&&x.status&&x.status!=='Pending'
  });
  var last=stages.length?stages[stages.length-1]:null;
  var actor=last&&last.person?displayPerson(last.person):'';
  var at=last&&last.at?last.at:'';

  return {
    title:state,
    sub:actor
      ? ('Last action by '+actor+(at?' · '+fmtDT(at):''))
      : (stockSourceLabel(r)+' workflow'),
    actor:actor,
    at:at
  };
}
function stockWorkflowCell(r){
  var w=stockWorkflowSummary(r),cls=r.status==='Rejected'?'rej-i':r.status==='Process Completed'?'ok-i':'pend-i';
  return '<div class="l1 '+cls+'">'+esc(w.title)+'</div><div class="l2">'+esc(w.sub)+'</div>';
}
