}
function refreshStageOptions(){
  var el=byId('f-stage');if(!el)return;
  var opts=pendingStageFilterOptions(TYPE),cur=F.stage||el.value||'';
  var allowed=opts.some(function(o){return o.v===cur});
  if(!allowed){cur='';F.stage=''}
  if(isStockReportType(TYPE)){
    el.innerHTML='<option value="">Not applicable for '+esc(TYPES[TYPE].name)+'</option>';
    el.value='';
    el.disabled=true;
    el.title='This document category uses its ERPNext document/workflow state instead of the common approval-level filter.';
    return
  }
  el.disabled=false;
  el.title='Filter requests by the stage where they are currently pending / held.';
  el.innerHTML='<option value="">All Pending Stages</option>'+opts.map(function(o){return '<option value="'+esc(o.v)+'"'+(cur===o.v?' selected':'')+'>'+esc(o.l)+'</option>'}).join('');
  el.value=cur
}
function setType(t){
  t=String(t||'ALL');

  if(!canAccessReportType(t)){
    TYPE='ALL';PAGE=1;SORT={k:'Request ID',dir:-1};F.stage='';
    renderTabs();refreshStageOptions();
    toast('Purchase Orders and Purchase Invoices are available only to System Manager or Stock Manager users.','err');
    refreshReport();
    return
  }

  TYPE=t;PAGE=1;SORT={k:'Request ID',dir:-1};
  /* Pending-stage meanings differ by approval type, so do not carry an old stage selection into another tab. */
  F.stage='';
  renderTabs();refreshStageOptions();refreshReport()
}

