   v23 APPROVAL ACTION / DECISION HELPERS
   ========================================================================= */
function normUser(v){return text(v).trim().toLowerCase()}
function isKPUser(){return ['kp@lifescc.com','kp'].indexOf(normUser(CURRENT_USER))>-1}
function isDiscountL4User(){return ['kp@lifescc.com','kp','bhuvan@lifescc.com'].indexOf(normUser(CURRENT_USER))>-1}
function isPurchaseApprover(){return ['kp@lifescc.com','kp','administrator','bhuvan@lifescc.com'].indexOf(normUser(CURRENT_USER))>-1}
function isBranchProfile(){return normUser(CURRENT_USER_PROFILE)==='branch user'||normUser(CURRENT_MODULE_PROFILE)==='branch user'}
function discountUserLevel(){
  /* L4 authority must be checked before L1/L2/L3 roles because Bhuvan also carries those roles. */
  if(isDiscountL4User())return 'L4';
  if(hasRole('life_discount_l3'))return 'L3';
  if(hasRole('life_discount_l2'))return 'L2';
  if(hasRole('life_discount_l1')||isBranchProfile())return 'L1';
  return ''
}
function discountLevelLabel(lvl){
  return {L1:'Branch Approval',L2:'Area Manager Approval',L3:'CEO Approval',L4:'Final Management Approval'}[text(lvl).toUpperCase()]||text(lvl,'Discount Approval')
}
function sameUser(a,b){return normUser(a)===normUser(b)}
function discountActionInfo(r){
  var raw=r&&r.raw||{},expected=text(raw.approval_level).toUpperCase(),mine=discountUserLevel(),selected=text(raw.selected_approver);
  var pending=r&&r.status==='Pending'&&statusKey(raw.status)!=='approved'&&statusKey(raw.status)!=='rejected';
  var branchOK=true;
  if(expected==='L1'&&BRANCH_FILTER_ACTIVE&&r.branch)branchOK=allowedBranch(r.branch);
  /* L4 is a shared Final Management authority: KP and Bhuvan may act even if the request was originally assigned to the other L4 approver. */
  var selectedOK=(expected==='L4'&&isDiscountL4User())||!selected||sameUser(selected,CURRENT_USER);
  var can=pending&&!!mine&&mine===expected&&branchOK&&selectedOK;
  var reason='';
  if(!pending)reason='This request is already '+text(raw.status,r.status)+'.';
  else if(!mine)reason='No discount approval level is assigned to this login.';
  else if(mine!==expected)reason='This request is waiting for '+discountLevelLabel(expected)+' ('+expected+').';
  else if(!branchOK)reason='This L1 request is outside your permitted branch.';
  else if(!selectedOK)reason='This request is assigned to '+cleanUser(selected)+'.';
  return {mine:mine,expected:expected,selected:selected,pending:pending,canAct:can,reason:reason}
}
function purchaseActionName(actions,want){
  want=String(want||'').toLowerCase();
  for(var i=0;i<(actions||[]).length;i++){
    var a=String(actions[i]||''),k=a.toLowerCase();
    if(k===want||k.indexOf(want)>-1)return a
  }
  return ''
}
async function loadRecordApprovalActions(r){
  r._workflowActions=[];
  r._workflowActionError='';
  r._conversionApprovalContext=null;
  r._conversionApprovalError='';
  if(!r)return r;

  if(['P2P','C2C','B2B'].indexOf(r.type)>-1){
    try{
      r._conversionApprovalContext=await api('life_approval_report_conversion_action',{
        operation:'context',
        doctype:r.sourceDoctype,
        docname:r.sourceName
      })||{};
    }catch(e){
      r._conversionApprovalError=errText(e);
      void 0
    }
  }

  if(r.status!=='Pending')return r;

  /* Purchase Order + Purchase Invoice use the real ERPNext Workflow API.
     The page adds an additional allowlist: only KP, Administrator and Bhuvan
     can receive purchase approval actions in this report. ERPNext still decides
     which transitions are actually valid for the current user and state. */
  if(
    r.type==='STK' &&
    (r.stockSource==='Purchase Order'||r.stockSource==='Purchase Invoice')
  ){
    if(!isPurchaseApprover())return r;

    try{
      var a=await api('frappe.model.workflow.get_common_transition_actions',{
        docs:JSON.stringify([r.raw||{}]),
        doctype:r.sourceDoctype
      });
      r._workflowActions=Array.isArray(a)?a:[];
    }catch(e){
      r._workflowActionError=errText(e);
      void 0
    }
  }

  return r
}
