  return v
    .replace(/<br\s*\/?\s*>/gi,' · ')
    .replace(/<[^>]+>/g,' ')
    .replace(/&nbsp;/gi,' ')
    .replace(/\s+/g,' ')
    .trim() || '—';
}

function piUnique(arr){
  var out=[];

  (arr||[]).forEach(function(v){
    v=text(v);
    if(v && out.indexOf(v)<0)out.push(v);
