function decisionSummaryHTML(r){
  var raw=r.raw||{},h='<div class="sec"><b>Approval Decision Information</b><i></i></div><div class="life-decision-grid">';
  if(r.type==='DISC'){
    var prior=num(r.priorApprovedPct),cur=num(raw.requested_discount_pct||r.discPct),after=prior+cur,curAmt=r.gross*(cur/100);
    h+=kvCard('Approval Level',esc(text(raw.approval_level,'—'))+' · '+esc(discountLevelLabel(raw.approval_level)));
    h+=kvCard('Original Bill',money(r.gross),'Already approved '+prior+'% · '+money(r.priorApprovedAmount||0));
    h+=kvCard('Current Request',cur+'% · '+money(curAmt),'After approval '+after+'%');
    h+=kvCard('Expected Payable',money(r.net),'Selected approver '+esc(cleanUser(raw.selected_approver)||'Not fixed'));
    h+='</div><div class="sec"><b>Discount Approval History</b><i></i></div>'+discountHistoryHTML(r);
    return h
  }
  if(r.type==='STK'&&r.stockSource==='Purchase Order'){
    h+=kvCard('Supplier',esc(r.vendor),esc(r.supplier||''));
    h+=kvCard('PO / Schedule Date',fmtD(r.poDate)+' / '+fmtD(r.scheduleDate),esc(r.company||''));
    h+=kvCard('Warehouse',esc(r.toWarehouse||r.fromWarehouse||'—'),'Linked MR: '+esc((r.linkedMaterialRequests||[]).join(', ')||'—'));
    h+=kvCard('Commercial Value',money(r.value),'Net '+money(r.netTotal||0)+' · Tax '+money(r.taxAmount||0));
    h+='</div>'+(r.remarks?'<div class="life-decision-remarks"><b>PO Remarks</b><div>'+esc(r.remarks)+'</div></div>':'');
    return h
  }
  if(r.type==='STK'&&r.stockSource==='Purchase Invoice'){
    h+=kvCard('Supplier / Bill',esc(r.vendor),esc(r.supplierBill||'—')+' · '+fmtD(r.supplierBillDate));
    h+=kvCard('Posting / Due Date',fmtD(r.postingDate)+' / '+fmtD(r.dueDate),esc(r.payablesBranch||r.branch||''));
    h+=kvCard('Linked Documents','PO '+esc((r.linkedPurchaseOrders||[]).join(', ')||'—'),'PR '+esc((r.linkedPurchaseReceipts||[]).join(', ')||'—'));
    h+=kvCard('Invoice Value',money(r.value),'Net '+money(r.netTotal||0)+' · Tax '+money(r.taxAmount||0)+(r.outstanding?' · Outstanding '+money(r.outstanding):''));
    h+='</div>'+(r.remarks?'<div class="life-decision-remarks"><b>PI Remarks</b><div>'+esc(r.remarks)+'</div></div>':'')+piPOComparisonHTML(r);
    return h
  }
  if(r.type==='P2P'){
    h+=kvCard('Original Package',esc(r.src),'Available '+money(r.avail)+' · Balance sessions '+(r.plan?r.plan.bal:'—'));
    h+=kvCard('New Package',esc(r.newPkg),'New value '+money(r.newVal));
    h+=kvCard('Unused Paid Value',money(r.credit),'Available '+money(r.avail)+' → '+money(r.newVal));
    h+=kvCard('Reason',esc(r.reason||'—'),'Current flow: Centre Manager → Audit Team → COO / Management');
  }else if(r.type==='C2C'){
    h+=kvCard('Transfer From',esc(r.client.name),esc(r.branch));
    h+=kvCard('Transfer To',esc(r.toClient.name),esc(r.toBranch));
    h+=kvCard('Transfer',r.sessions+' sessions · '+money(r.transVal),esc(r.pkg));
    h+=kvCard('Reason',esc(r.reason||'—'),'Centre Manager → Audit / Corporate Team → COO / Management');
  }else if(r.type==='B2B'){
    h+=kvCard('Transfer From',esc(r.branch),esc(r.client.name));
    h+=kvCard('Transfer To',esc(r.toBranch),'Client continues at destination branch');
    h+=kvCard('Package / Value',r.sessions+' sessions · '+money(r.transVal),esc(r.pkg));
    h+=kvCard('Reason',esc(r.reason||'—'),'Branch Manager → Audit Team → COO / Management');
  }else{
    h+=kvCard('Document',esc(r.reqId),esc(r.sourceStatus||r.status));
  }
  return h+'</div>'
}
