   show matches, and only populate the input when the approver selects a result. */
var LIFE_CONV_THERAPY_SEARCH={timer:0,input:null,dropdown:null,seq:0};
function lifeConvHideTherapySearch(){
  var d=LIFE_CONV_THERAPY_SEARCH.dropdown;
  if(d){d.style.display='none';d.innerHTML=''}
  LIFE_CONV_THERAPY_SEARCH.input=null
}
function lifeConvEnsureTherapyDropdown(){
  var d=byId('life-conv-therapy-dropdown');
  if(d){LIFE_CONV_THERAPY_SEARCH.dropdown=d;return d}
  d=document.createElement('div');d.id='life-conv-therapy-dropdown';d.className='life-conv-therapy-dropdown';
  document.body.appendChild(d);LIFE_CONV_THERAPY_SEARCH.dropdown=d;
  return d
}
function lifeConvPositionTherapyDropdown(input){
  var d=lifeConvEnsureTherapyDropdown();if(!input||!d)return;
  var r=input.getBoundingClientRect(),w=Math.max(300,r.width);
  d.style.left=Math.max(8,Math.min(r.left,window.innerWidth-w-8))+'px';
  d.style.top=Math.min(window.innerHeight-220,r.bottom+4)+'px';
  d.style.width=Math.min(w,window.innerWidth-16)+'px'
}
function lifeConvRenderTherapyResults(input,rows,q){
  if(LIFE_CONV_THERAPY_SEARCH.input!==input)return;
  var d=lifeConvEnsureTherapyDropdown();lifeConvPositionTherapyDropdown(input);
  if(!rows.length){d.innerHTML='<div class="life-conv-therapy-empty">No Therapy Type found for <b>'+esc(q)+'</b></div>';d.style.display='block';return}
  d.innerHTML=rows.map(function(t){
    var nm=text(t.name),label=text(t.therapy_type,nm),unit=text(t.healthcare_service_unit);
    return '<button type="button" class="life-conv-therapy-option" data-name="'+esc(nm)+'"><b>'+esc(label)+'</b>'+(nm!==label?'<span>'+esc(nm)+'</span>':'')+(unit?'<small>'+esc(unit)+'</small>':'')+'</button>'
  }).join('');
  d.style.display='block';
  d.querySelectorAll('.life-conv-therapy-option').forEach(function(btn){
    btn.addEventListener('mousedown',function(e){e.preventDefault()});
    btn.addEventListener('click',function(e){
      e.preventDefault();e.stopPropagation();
      input.value=text(btn.getAttribute('data-name'));input.dataset.therapySelected='1';
      lifeConvHideTherapySearch();input.dispatchEvent(new Event('change',{bubbles:true}))
    })
  })
}
async function lifeConvSearchTherapyType(input,q){
  var seq=++LIFE_CONV_THERAPY_SEARCH.seq;
  LIFE_CONV_THERAPY_SEARCH.input=input;
  var d=lifeConvEnsureTherapyDropdown();lifeConvPositionTherapyDropdown(input);
  d.innerHTML='<div class="life-conv-therapy-empty">Searching Therapy Types…</div>';d.style.display='block';
  try{
    var rows=await api('frappe.client.get_list',{
      doctype:'Therapy Type',
      fields:['name','therapy_type','healthcare_service_unit','disabled'],
      filters:[['Therapy Type','name','like','%'+q+'%'],['Therapy Type','disabled','=',0]],
      order_by:'name asc',limit_page_length:20
    })||[];
    if(seq!==LIFE_CONV_THERAPY_SEARCH.seq)return;
    lifeConvRenderTherapyResults(input,rows,q)
  }catch(e){
    if(seq!==LIFE_CONV_THERAPY_SEARCH.seq)return;
    d.innerHTML='<div class="life-conv-therapy-empty life-conv-therapy-error">Therapy Type search failed</div>';d.style.display='block';
    void 0
  }
}
function lifeConvBindTherapySearch(scope){
  scope=scope||document;
  scope.querySelectorAll('.life-conv-therapy').forEach(function(input){
    if(input.dataset.lifeTherapySearchBound==='1')return;
    input.dataset.lifeTherapySearchBound='1';
    input.addEventListener('input',function(){
      input.dataset.therapySelected='0';clearTimeout(LIFE_CONV_THERAPY_SEARCH.timer);
      var q=text(input.value).trim();
      if(q.length<2){lifeConvHideTherapySearch();return}
      LIFE_CONV_THERAPY_SEARCH.input=input;
      LIFE_CONV_THERAPY_SEARCH.timer=setTimeout(function(){lifeConvSearchTherapyType(input,q)},250)
    });
    input.addEventListener('focus',function(){var q=text(input.value).trim();if(!input.disabled&&q.length>=2){LIFE_CONV_THERAPY_SEARCH.input=input;lifeConvSearchTherapyType(input,q)}});
    input.addEventListener('blur',function(){setTimeout(function(){if(LIFE_CONV_THERAPY_SEARCH.input===input)lifeConvHideTherapySearch()},160)})
  })
}
document.addEventListener('mousedown',function(e){
  var d=byId('life-conv-therapy-dropdown');
  if(d&&d.style.display!=='none'&&!e.target.closest('#life-conv-therapy-dropdown')&&!e.target.closest('.life-conv-therapy'))lifeConvHideTherapySearch()
});
window.addEventListener('resize',function(){if(LIFE_CONV_THERAPY_SEARCH.input)lifeConvPositionTherapyDropdown(LIFE_CONV_THERAPY_SEARCH.input)},{passive:true});
window.addEventListener('scroll',function(){if(LIFE_CONV_THERAPY_SEARCH.input)lifeConvPositionTherapyDropdown(LIFE_CONV_THERAPY_SEARCH.input)},{passive:true,capture:true});
function lifeConvToggleEdit(on){
  document.querySelectorAll('.life-conv-table input,.life-conv-remove').forEach(function(el){el.disabled=!on});
  var add=byId('life-conv-add-row');if(add)add.disabled=!on;
  var rw=byId('life-conv-edit-reason-wrap');if(rw)rw.style.display=on?'block':'none';
  if(on)setTimeout(function(){lifeConvBindTherapySearch(byId('life-conv-table-body')||document)},0);else lifeConvHideTherapySearch()
}
function lifeConvAddRow(){
  var body=byId('life-conv-table-body');if(!body)return;
  var empty=body.querySelector('.life-conv-empty-row');if(empty)empty.remove();
  var idx=body.querySelectorAll('.life-conv-edit-row').length;
  body.insertAdjacentHTML('beforeend',lifeConvTableRowHTML({therapy_type:'',qty:1,amount:0},idx));
  var last=body.lastElementChild;if(last){last.querySelectorAll('input,.life-conv-remove').forEach(function(el){el.disabled=false});lifeConvBindTherapySearch(last)}
}
function lifeConvRemoveRow(btn){
  var row=btn&&btn.closest('.life-conv-edit-row');if(row)row.remove();
  var body=byId('life-conv-table-body');if(body&&!body.querySelector('.life-conv-edit-row'))body.innerHTML='<tr class="life-conv-empty-row"><td colspan="6">No therapy rows. Add at least one row before approval.</td></tr>'
}
function lifeConvCollectRows(){
  var ctx=lifeConvContext(CUR_REC),base=ctx.table_rows||[],rows=[];
  document.querySelectorAll('#life-conv-table-body .life-conv-edit-row').forEach(function(tr,idx){
    var old=base[idx]||{},o={};Object.keys(old).forEach(function(k){o[k]=old[k]});
    o.therapy_type=text((tr.querySelector('.life-conv-therapy')||{}).value);
    o.qty=num((tr.querySelector('.life-conv-qty')||{}).value);
    o.amount=num((tr.querySelector('.life-conv-amount')||{}).value);
    rows.push(o)
  });
  return rows
}
function lifeConvSignatureHTML(){
  return '<div class="life-conv-sign"><label>Signature *</label><canvas id="life-conv-signature" width="720" height="150"></canvas><div class="life-conv-sign-foot"><button type="button" onclick="lifeConvClearSignature()">Clear Signature</button><span id="life-conv-sign-status">Sign above before Approve / Reject</span></div></div>'
}
var LIFE_CONV_SIGNATURE_DATA='';
function initLifeApprovalSignaturePad(){
  LIFE_CONV_SIGNATURE_DATA='';
  var c=byId('life-conv-signature');if(!c)return;
  var ctx=c.getContext('2d'),drawing=false,last=null;
  function pos(ev){var r=c.getBoundingClientRect(),p=ev.touches&&ev.touches[0]?ev.touches[0]:ev;return{x:(p.clientX-r.left)*(c.width/r.width),y:(p.clientY-r.top)*(c.height/r.height)}}
  function start(ev){drawing=true;last=pos(ev);ev.preventDefault()}
  function move(ev){if(!drawing)return;var p=pos(ev);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#173d2b';ctx.stroke();last=p;LIFE_CONV_SIGNATURE_DATA=c.toDataURL('image/png');var st=byId('life-conv-sign-status');if(st)st.textContent='Signature captured';ev.preventDefault()}
  function stop(){drawing=false;last=null}
  c.addEventListener('mousedown',start);c.addEventListener('mousemove',move);window.addEventListener('mouseup',stop);
  c.addEventListener('touchstart',start,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',stop,{passive:false})
}
function lifeConvClearSignature(){var c=byId('life-conv-signature');if(c)c.getContext('2d').clearRect(0,0,c.width,c.height);LIFE_CONV_SIGNATURE_DATA='';var st=byId('life-conv-sign-status');if(st)st.textContent='Sign above before Approve / Reject'}
