  var h='<div class="life-action-box life-conv-action"><div class="life-action-head"><div><b>'+esc((lifeApprovalRoleLabel(ctx.role_label)||'Approval')+' Decision')+'</b><span>'+esc(r.reqId)+' · '+esc(ctx.branch||r.branch||'')+'</span></div><div class="life-action-user">Logged in: <b>'+esc((CURRENT_EMP&&CURRENT_EMP.employee_name)||cleanUser(CURRENT_USER))+'</b></div></div>';
  if(err)return h+'<div class="life-action-readonly">Approval API is not ready: '+esc(err)+'</div></div>';
  if(!ctx.pending_role)return h+'<div class="life-action-readonly">This request is not waiting for another approval action.</div></div>';
  if(!ctx.can_act)return h+'<div class="life-action-readonly">🔒 '+esc(ctx.reason||('Waiting for '+lifeApprovalRoleLabel(ctx.role_label)))+'</div></div>';

  h+='<div class="life-conv-form">';
  if((ctx.centre_managers||[]).length){h+='<div class="life-conv-field"><label>'+esc(ctx.role_label)+' *</label><select id="life-conv-manager">'+lifeConvManagerOptions(ctx)+'</select></div>'}
  else{h+='<div class="life-conv-field"><label>Approver</label><div class="life-conv-readonly">'+esc(displayPerson(ctx.approver_name)||cleanUser(CURRENT_USER))+'</div></div>'}
  h+='<div class="life-conv-field life-conv-remarks"><label>Approval Remarks'+(ctx.remarks_required_for_approve||ctx.remarks_required_for_reject?' *':'')+'</label><textarea id="life-conv-remarks" placeholder="Write approval / rejection remarks"></textarea></div>';
  h+='</div>';
  h+=lifeConvEditableTableHTML(ctx);
  if(ctx.require_signature||r.type==='B2B')h+=lifeConvSignatureHTML();
  h+='<div class="life-action-buttons"><button class="life-reject-btn" onclick="lifeApprovalConversionAction(\'Reject\')">✕ Reject</button><button class="life-approve-btn" onclick="lifeApprovalConversionAction(\'Approve\')">✓ Approve</button></div></div>';
  return h
}
function lifeApprovalB2BIsFinalContext(ctx){
  ctx=ctx||{};
  var s=(text(ctx.pending_role)+' '+text(ctx.role_label)).toLowerCase();
  return s.indexOf('coo')>-1||s.indexOf('final')>-1||s.indexOf('management')>-1
}
function lifeApprovalWordCount(v){
  v=text(v).trim();
  return v?v.split(/\s+/).filter(Boolean).length:0
}
async function lifeApprovalB2BFinalizeBranchTransfer(r){
  if(!r||r.type!=='B2B')return {skipped:true};

  var req=await api('frappe.client.get',{doctype:r.sourceDoctype||'Client Transfer Request Form',name:r.sourceName});
  req=req||{};

  var patient=text(req.client_full_name||req.client_id__crm_no||req.client);
  var target=text(req.transfer_to_branch||r.toBranch);
  if(!patient)throw new Error('Patient / Client is missing. Cannot apply the final branch transfer.');
  if(!target)throw new Error('Transfer To Branch is missing. Cannot update Patient / Therapy Plan branch.');

  try{
    await api('frappe.client.set_value',{doctype:'Patient',name:patient,fieldname:{branch_name:target,custom_branch:target}})
  }catch(e1){
    try{
      await api('frappe.client.set_value',{doctype:'Patient',name:patient,fieldname:{branch_name:target}})
    }catch(e2){
      throw new Error('Final approval was saved, but Patient branch update failed: '+errText(e2||e1))
    }
  }

  try{
    var pdoc=await api('frappe.client.get',{doctype:'Patient',name:patient})||{};
    var childField=Array.isArray(pdoc.custom_brnch_list)?'custom_brnch_list':Array.isArray(pdoc.custom_branch_list)?'custom_branch_list':'';
    if(childField){
      var branchRows=(pdoc[childField]||[]).slice();
      var exists=branchRows.some(function(x){return text(x&&x.branch)===target});
      if(!exists){
        branchRows.push({branch:target,transfer_date:new Date().toISOString().slice(0,10),remarks:'Branch updated through Client Transfer Request '+text(r.sourceName||r.reqId)});
        var update={};update[childField]=branchRows;
        await api('frappe.client.set_value',{doctype:'Patient',name:patient,fieldname:update})
      }
    }
  }catch(historyErr){
    void 0
  }

  var plans=await api('frappe.client.get_list',{
    doctype:'Therapy Plan',
    fields:['name','patient','custom_transfer_branch'],
    filters:[['patient','=',patient]],
    limit_page_length:100
  })||[];

  var updated=0;
  for(var i=0;i<plans.length;i++){
    var plan=plans[i]||{};if(!plan.name)continue;
    try{
      if(text(plan.custom_transfer_branch)!==target){
        await api('frappe.client.set_value',{doctype:'Therapy Plan',name:plan.name,fieldname:{custom_transfer_branch:target}})
      }
      updated++
    }catch(planErr){
      void 0
    }
  }

  return {patient:patient,branch:target,therapyPlansUpdated:updated}
}
async function lifeApprovalConversionAction(action){
  var r=CUR_REC;if(!r||['P2P','C2C','B2B'].indexOf(r.type)<0)return;
  var ctx=lifeConvContext(r);if(!ctx.can_act){toast(ctx.reason||'Approval not allowed','err');return}
  var remarks=text((byId('life-conv-remarks')||{}).value),isReject=String(action).toLowerCase()==='reject';
  if((isReject&&ctx.remarks_required_for_reject)||(!isReject&&ctx.remarks_required_for_approve)){if(!remarks){toast('Approval remarks are required','err');return}}
  var manager=text((byId('life-conv-manager')||{}).value);
  if((ctx.centre_managers||[]).length&&!manager){toast('Select the '+ctx.role_label+' before saving','err');return}
  if((ctx.require_signature||r.type==='B2B')&&!LIFE_CONV_SIGNATURE_DATA){toast('Signature is required','err');return}
  if(r.type==='B2B'&&/branch manager|audit/i.test(text(ctx.role_label))&&lifeApprovalWordCount(remarks)>100){toast(ctx.role_label+' remarks should be within 100 words','err');return}
  var rows=[],editReason='';
  if(ctx.allow_table_edit){rows=lifeConvCollectRows();var editOn=!!(byId('life-conv-edit-toggle')&&byId('life-conv-edit-toggle').checked);editReason=editOn?text((byId('life-conv-edit-reason')||{}).value):''}
  if(!window.confirm(action+' '+r.reqId+' as '+ctx.role_label+'?'))return;
  var type=r.type,source=r.sourceName;
  showLoad(true,action+' '+r.reqId+'…','Validating current stage and logged-in approval authority');
  try{
    var res=await api('life_approval_report_conversion_action',{
      operation:'action',doctype:r.sourceDoctype,docname:r.sourceName,action:action,remarks:remarks,
      approver_employee:manager,signature:LIFE_CONV_SIGNATURE_DATA,table_rows_json:ctx.allow_table_edit?JSON.stringify(rows):'',table_edit_reason:editReason
    })||{};
    if(res.run_p2p_final_automation){
      showLoad(true,'Running P2P automation…','Updating the Therapy Plan after final COO approval');
      var auto=await api('p2p_run_final_automation',{request_name:r.sourceName});
      if(auto&&auto.ok===false)throw new Error(auto.message||'P2P final automation failed')
    }
    if(r.type==='C2C'&&String(action).toLowerCase()==='approve'&&res.next_step){
      try{await api('send_client_conversion_step_email',{docname:r.sourceName,next_step:res.next_step})}catch(mailErr){void 0}
    }

    var b2bFinalizeError='';
    if(r.type==='B2B'&&String(action).toLowerCase()==='approve'&&lifeApprovalB2BIsFinalContext(ctx)){
      showLoad(true,'Completing B2B transfer…','Updating Patient branch and Therapy Plans after final COO approval');
      try{
        var b2bDone=await lifeApprovalB2BFinalizeBranchTransfer(r);
        void 0
      }catch(b2bErr){
        b2bFinalizeError=errText(b2bErr);
        void 0
      }
    }

    toast((res.role_label||ctx.role_label)+' '+(String(action).toLowerCase()==='approve'?'approved':'rejected'),'ok');
    await lifeApprovalRefreshAndReopen(type,source);
    if(b2bFinalizeError){
      alert('Final COO approval was saved, but the B2B Patient / Therapy Plan branch update failed: '+b2bFinalizeError)
    }
  }catch(e){alert(action+' failed: '+errText(e));void 0}
  finally{showLoad(false)}
}
function lifeApprovalPendingStageIndex(r){
  var stages=(r&&r.stages)||[];
  for(var i=0;i<stages.length;i++){
    if(String(stages[i].status||'').toLowerCase()==='pending')return i;
  }
  return -1
}
function lifeApprovalExternalRole(r){
  var idx=lifeApprovalPendingStageIndex(r);
  if(idx===0)return 'cm';
  if(idx===1)return 'ops';
  if(idx===2)return 'coo';
  return ''
}
function lifeApprovalExternalStageLabel(r){
  var idx=lifeApprovalPendingStageIndex(r),stages=(r&&r.stages)||[];
  return idx>-1&&stages[idx]?text(stages[idx].label||stages[idx].name,'Approval'):''
}
function lifeApprovalSourcePagePath(r){
  if(!r)return '';
  if(r.type==='P2P')return '/package-conversion-for-p2p';
  if(r.type==='C2C')return '/package-conversion-C2C';
  return ''
}
function lifeApprovalSourceUrl(r){
  var path=lifeApprovalSourcePagePath(r);if(!path)return '';
  var role=lifeApprovalExternalRole(r);
  var returnTo=window.location.pathname+window.location.search;
  return path+'?tab=approval'+
    (role?'&role='+encodeURIComponent(role):'')+
    '&request='+encodeURIComponent(r.sourceName||r.reqId||'')+
    '&return_to='+encodeURIComponent(returnTo)
}
function lifeNormalizeWebsitePath(path){
  path=text(path).trim();
  if(!path)return '';
  path=path.replace(/^https?:\/\/[^/]+/i,'').split('?')[0].split('#')[0];
  if(path.charAt(0)!=='/')path='/'+path;
  path=path.replace(/\/{2,}/g,'/');
  if(path.length>1)path=path.replace(/\/$/,'');
  return path
}
function lifeBillingCandidateScore(row){
  row=row||{};
  var title=text(row.title).toLowerCase();
  var name=text(row.name).toLowerCase();
  var route=text(row.route).toLowerCase();
  var all=[title,name,route].join(' ');
  var score=0;
  if(all.indexOf('single page billing system')>-1)score+=2000;
  if(title.indexOf('billing module')>-1)score+=1600;
  if(title==='billing'||route==='/billing'||route==='billing')score+=1400;
  if(title.indexOf('billing')>-1)score+=900;
  if(route.indexOf('billing')>-1)score+=850;
  if(name.indexOf('billing')>-1)score+=650;
  if(all.indexOf('client billing')>-1)score+=450;
  if(all.indexOf('invoice')>-1)score+=100;
  if(all.indexOf('approvals report')>-1||route.indexOf('approvals-report')>-1)score-=3000;
  if(all.indexOf('stock')>-1||all.indexOf('asset')>-1||all.indexOf('package conversion')>-1)score-=1000;
  return score
}
async function lifeVerifyBillingPath(path){
  path=lifeNormalizeWebsitePath(path);
  if(!path)return false;
  try{
    var resp=await fetch(window.location.origin+path,{method:'GET',credentials:'same-origin',cache:'no-store',redirect:'follow'});
    if(!resp||!resp.ok)return false;
    var html=await resp.text();
    var low=String(html||'').toLowerCase();
    return low.indexOf('discount approvals')>-1||
      low.indexOf('lifescc.billing.bootstrap')>-1||
      low.indexOf('v-approvals')>-1||
      (low.indexOf('client billing')>-1&&low.indexOf('recent bills')>-1)
  }catch(e){return false}
}
