var LIFE_DISCOUNT_WATCH_TIMER=null;
var LIFE_DISCOUNT_CHILD_TIMER=null;
function lifeStopDiscountWatch(){
  if(LIFE_DISCOUNT_WATCH_TIMER){clearInterval(LIFE_DISCOUNT_WATCH_TIMER);LIFE_DISCOUNT_WATCH_TIMER=null}
  if(LIFE_DISCOUNT_CHILD_TIMER){clearInterval(LIFE_DISCOUNT_CHILD_TIMER);LIFE_DISCOUNT_CHILD_TIMER=null}
}
function lifeWatchDiscountDecision(r,child){
  lifeStopDiscountWatch();
  if(!r)return;
  var req=text(r.sourceName||r.reqId);
  var type=r.type,source=r.sourceName;
  var checking=false,started=Date.now();
  LIFE_DISCOUNT_WATCH_TIMER=setInterval(async function(){
    if(checking)return;
    if(Date.now()-started>30*60*1000){lifeStopDiscountWatch();return}
    if(child&&child.closed){lifeStopDiscountWatch();return}
    checking=true;
    try{
      var d=await getDoc('Discount Approval Request',req);
      var st=text(d&&d.status);
      if(st&&st.toLowerCase()!=='pending'){
        lifeStopDiscountWatch();
        try{if(child&&!child.closed)child.close()}catch(e){}
        try{window.focus()}catch(e){}
        toast('Discount request '+st.toLowerCase()+'. Refreshing the Approvals Report…',st.toLowerCase()==='approved'?'ok':'warn');
        await lifeApprovalRefreshAndReopen(type,source)
      }
    }catch(e){void 0}
    finally{checking=false}
  },1800)
}
function lifeFocusExactBillingDiscountRequest(child,r){
  var req=text(r&& (r.sourceName||r.reqId));
  if(!child||child.closed||!req)return;
  var tries=0,maxTries=80;
  var timer=setInterval(function(){
    tries++;
    if(!child||child.closed||tries>maxTries){clearInterval(timer);return}
    try{
      var list=child.BILL_REQS||[];
      var idx=-1;
      for(var i=0;i<list.length;i++){
        if(text(list[i]&&list[i].name)===req){idx=i;break}
      }
      if(idx<0)return;

      var body=child.document&&child.document.getElementById('bill-body');
      if(!body)return;
      var tables=body.querySelectorAll('table.tbl');
      var approvalTable=null;
      for(var t=0;t<tables.length;t++){
        var head=text(tables[t].querySelector('thead')&&tables[t].querySelector('thead').textContent).toLowerCase();
        if(head.indexOf('level')>-1&&head.indexOf('approver')>-1&&head.indexOf('status')>-1){
          approvalTable=tables[t];break
        }
      }
      if(!approvalTable)return;
      var rows=approvalTable.querySelectorAll('tbody tr');
      var row=rows[idx];
      if(!row)return;

      row.style.outline='3px solid #0F8A5F';
      row.style.outlineOffset='-3px';
      row.style.background='#ECFDF5';
      row.setAttribute('data-life-focused-discount-request',req);

      var badge=child.document.createElement('div');
      badge.textContent='Exact approval request · '+req;
      badge.style.cssText='display:inline-block;margin:0 0 8px;padding:5px 10px;border-radius:12px;background:#0B6B4A;color:#fff;font-size:11px;font-weight:800;';
      var holder=approvalTable.parentElement;
      if(holder&&!holder.querySelector('[data-life-discount-focus-label]')){
        badge.setAttribute('data-life-discount-focus-label','1');
        holder.parentElement.insertBefore(badge,holder)
      }
      try{row.scrollIntoView({behavior:'smooth',block:'center'})}catch(e){try{row.scrollIntoView()}catch(_){}}
      clearInterval(timer)
    }catch(e){}
  },250)
}
function lifeOpenExistingBillingApproval(child,r){
  var attempts=0,maxAttempts=240;
  if(LIFE_DISCOUNT_CHILD_TIMER)clearInterval(LIFE_DISCOUNT_CHILD_TIMER);
  LIFE_DISCOUNT_CHILD_TIMER=setInterval(function(){
    attempts++;
    if(!child||child.closed||attempts>maxAttempts){
      clearInterval(LIFE_DISCOUNT_CHILD_TIMER);LIFE_DISCOUNT_CHILD_TIMER=null;
      if(attempts>maxAttempts)toast('Billing opened, but the report could not automatically open its approval drawer. Use the Billing Approvals tab manually.','warn');
      return
    }
    try{
      if(typeof child.showView!=='function'||typeof child.openBill!=='function')return;
      if(child.CURRENT_USER&&String(child.CURRENT_USER)==='Guest')return;
      child.showView('approvals');
      try{
