        if(input)input.value=r.invoice||''
      }catch(e){}
      child.openBill(r.invoice);
      lifeFocusExactBillingDiscountRequest(child,r);
      try{child.focus()}catch(e){}
      clearInterval(LIFE_DISCOUNT_CHILD_TIMER);LIFE_DISCOUNT_CHILD_TIMER=null;
    }catch(e){}
  },250)
}
