function approvalActionHTML(r){
  if(!r)return '';

  /*
   * v53:
   * P2P and C2C approvals are performed directly inside the Approvals Report
   * details modal using the centralized server-side conversion approval API.
   *
   * The API context remains the authority for:
   * - current pending stage
   * - whether the logged-in user can act
   * - valid branch manager / Centre Manager selection
   * - remarks/signature requirements
   * - Audit/COO final-table editing
   *
   * C2C final approval does NOT call the P2P automation method.
   * The C2C document save/After Save flow remains responsible for package
   * transfer automation; the existing next-step email hook is preserved.
   *
   * B2B remains direct in the modal.
   */
  if(['P2P','C2C','B2B'].indexOf(r.type)>-1){
    var convCtx=lifeConvContext(r);

    /* Do not render an Approval Decision card after the workflow has ended.
       Pending requests still render the action/locked panel normally. */
    if(r.status!=='Pending'&&!convCtx.pending_role)return '';

    return conversionApprovalActionHTML(r)
  }
  if(r.type==='DISC')return discountApprovalRedirectHTML(r);
  if(r.type==='STK'&&r.stockSource==='Purchase Invoice'){
    var piActions=r._workflowActions||[];
    var piApprove=purchaseActionName(piActions,'approve');
    var piReject=purchaseActionName(piActions,'reject');
    var piState=text((r.raw||{}).workflow_state||r.workflowState||r.status,'—');

    var ph='<div class="life-action-box">'+
      '<div class="life-action-head">'+
        '<div><b>Purchase Invoice Decision</b><span>'+esc(piState)+'</span></div>'+
        '<div class="life-action-user">Authorized: <b>KP / Administrator / Bhuvan</b></div>'+
      '</div>';

    if(!isPurchaseApprover()){
      ph+='<div class="life-action-readonly">🔒 View only. Purchase Invoice approval from this report is restricted to KP, Administrator and Bhuvan.</div>';
      return ph+'</div>'
    }

    if(r.status==='Process Completed'){
      ph+='<div class="life-action-readonly">✓ This Purchase Invoice is already approved and submitted.</div>';
      return ph+'</div>'
    }

    if(r.status==='Rejected'){
      ph+='<div class="life-action-readonly">✕ This Purchase Invoice is currently rejected.</div>';
      return ph+'</div>'
    }

    if(piApprove||piReject){
      ph+='<div class="life-action-buttons">'+
        (piReject?'<button type="button" class="life-reject-btn" onclick="lifeApprovalPurchaseAction(\''+lifeInvoiceJsValue(piReject)+'\')">✕ '+esc(piReject)+'</button>':'')+
        (piApprove?'<button type="button" class="life-approve-btn" onclick="lifeApprovalPurchaseAction(\''+lifeInvoiceJsValue(piApprove)+'\')">✓ '+esc(piApprove)+'</button>':'')+
      '</div>';
      return ph+'</div>'
    }

    var piMsg='';
    if(r._workflowActionError){
      piMsg='Workflow actions could not be read: '+esc(r._workflowActionError);
    }else if(statusKey(piState)==='draft'){
      piMsg='This Purchase Invoice is still Draft. It must first be sent for approval by the Stock Manager.';
    }else{
      piMsg='No Approve / Reject transition is available to this login at the current Purchase Invoice workflow state.';
    }

    ph+='<div class="life-action-readonly">'+piMsg+'</div>';
    return ph+'</div>'
  }
  if(r.type==='STK'&&r.stockSource==='Purchase Order'){
    var label=r.stockSource,actions=r._workflowActions||[],approve=purchaseActionName(actions,'approve'),reject=purchaseActionName(actions,'reject');
    var h='<div class="life-action-box"><div class="life-action-head"><div><b>'+esc(label)+' Decision</b><span>'+esc(r.workflowState||r.status)+'</span></div>'+
      '<div class="life-action-user">Purchase approver: <b>KP / Administrator / Bhuvan</b></div></div>';
    if(!isPurchaseApprover()){
      h+='<div class="life-action-readonly">🔒 View only. Purchase Order approval is assigned to KP / Administrator / Bhuvan.</div>'
    }else if(r.status!=='Pending'){
      h+='<div class="life-action-readonly">This document is already '+esc(r.status)+'.</div>'
    }else if(approve||reject){
      h+='<div class="life-action-buttons">'+(reject?'<button class="life-reject-btn" onclick="lifeApprovalPurchaseAction(\''+lifeInvoiceJsValue(reject)+'\')">✕ '+esc(reject)+'</button>':'')+
        (approve?'<button class="life-approve-btn" onclick="lifeApprovalPurchaseAction(\''+lifeInvoiceJsValue(approve)+'\')">✓ '+esc(approve)+'</button>':'')+'</div>'
    }else{
      h+='<div class="life-action-readonly">'+(r._workflowActionError?'Workflow actions could not be read: '+esc(r._workflowActionError):'No Approve / Reject transition is available to this login at the current Purchase Order workflow state.')+'</div>'
    }
    return h+'</div>'
  }
  return ''
}
