async function lifeApprovalPurchaseAction(action){
  var r=CUR_REC;

  if(
    !r ||
    r.type!=='STK' ||
    (r.stockSource!=='Purchase Order'&&r.stockSource!=='Purchase Invoice')
  )return;

  if(!isPurchaseApprover()){
    toast(r.stockSource+' approval is restricted to KP / Administrator / Bhuvan','err');
    return
  }

  action=text(action);
  if(!action){
    toast('Workflow action is missing','err');
    return
  }

  /* Never trust only the inline button value. The action must also be one of the
     transitions ERPNext returned for this exact document, login and workflow state. */
  var available=r._workflowActions||[];
  var validAction='';

  for(var i=0;i<available.length;i++){
    if(String(available[i]).toLowerCase()===String(action).toLowerCase()){
      validAction=available[i];
      break
    }
  }

  if(!validAction){
    toast('This workflow action is not available for the current '+r.stockSource+' state.','err');
    return
  }

  action=validAction;

  var isReject=String(action).toLowerCase().indexOf('reject')>-1;
  var reason='';

  if(isReject){
    reason=window.prompt('Rejection reason (required):','');
    if(reason===null)return;

    reason=text(reason);
    if(!reason){
      toast('Rejection reason is required','err');
      return
    }
  }else{
    var state=text((r.raw||{}).workflow_state||r.workflowState||r.status,'—');
    if(!window.confirm(action+' '+r.stockSource+' '+r.reqId+'?\n\nCurrent state: '+state))return
  }

  var type=r.type;
  var source=r.sourceName;
  var oldRemarks=text((r.raw||{}).remarks);

  showLoad(
    true,
    action+' '+r.reqId+'…',
    'Applying the real ERPNext '+r.stockSource+' workflow transition'
  );

  try{
    await api('frappe.model.workflow.apply_workflow',{
      doc:JSON.stringify(r.raw||{}),
      action:action
    });

    /* Rejection reason is supplementary. The Workflow transition happens first,
       so a remarks write failure never falsely reports the approval as failed. */
    if(isReject&&reason){
      try{
        var approver=(CURRENT_EMP&&CURRENT_EMP.employee_name)||cleanUser(CURRENT_USER);
        var note='Approval Report rejection by '+approver+': '+reason;

        await api('frappe.client.set_value',{
          doctype:r.sourceDoctype,
          name:r.sourceName,
          fieldname:'remarks',
          value:(oldRemarks?oldRemarks+'\\n':'')+note
        });
      }catch(noteErr){
        void 0
      }
    }

    toast(r.stockSource+' '+action+' completed','ok');
    await lifeApprovalRefreshAndReopen(type,source)

  }catch(e){
    alert(action+' failed: '+errText(e));
    void 0

  }finally{
    showLoad(false)
  }
}

