function ensureApprovalActionMounted(r){
  if(!r)return;
  var eligible=['P2P','C2C','B2B','DISC'].indexOf(r.type)>-1 ||
    (r.type==='STK'&&(r.stockSource==='Purchase Order'||r.stockSource==='Purchase Invoice'));
  if(!eligible)return;
  var body=byId('m-body');if(!body)return;
  var existing=body.querySelector('.life-action-box');
  if(existing)return;
  var html=approvalActionHTML(r);
  if(html){
    body.insertAdjacentHTML('beforeend',html);
    void 0;
  }else if(r.type==='P2P'||r.type==='C2C'||r.type==='B2B'||r.type==='DISC'){
    /* Expected when the conversion workflow is complete/rejected, or when
       the current login has no actionable control to mount. */
    return;
  }else{
    body.insertAdjacentHTML('beforeend','<div class="life-action-box"><div class="life-action-readonly">Approval action renderer returned no content for this request. Please check the current request type/stage.</div></div>');
    void 0;
  }
}
async function openRec(no){
  var r=null;for(var i=0;i<DATA.length;i++)if(DATA[i].no===no){r=DATA[i];break}
  if(!r)return;CUR_REC=r;
  byId('m-title').textContent=(r.type==='STK'?stockSourceLabel(r):r.client.name)+'  ·  '+reportTypeMeta(r).name;
  byId('m-sub').textContent=r.reqId+'   ·   '+(r.branch||'Branch not resolved')+'   ·   Requested '+fmtDT(r.reqDT);
  byId('m-body').innerHTML='<div class="life-load-mini">Loading complete ERPNext request…</div>';
  byId('ov').classList.add('on');document.body.style.overflow='hidden';
  await hydrateRecord(r);
  await loadRecordApprovalActions(r);
  CUR_REC=r;byId('m-body').innerHTML=recHTML(r);ensureApprovalActionMounted(r);if(r.type==='P2P'||r.type==='C2C'||r.type==='B2B'||(r.type==='STK'&&(r.stockSource==='Purchase Order'||r.stockSource==='Purchase Invoice'))){setTimeout(function(){if(!byId('m-body').querySelector('.life-action-box'))void 0},0)}setTimeout(initLifeApprovalSignaturePad,30)
}
