function sortRowsForExport(list){
  var out=(list||[]).slice(),C=COLS(TYPE),col=null;

  for(var i=0;i<C.length;i++){
    if(C[i].h===SORT.k){
      col=C[i];
      break;
    }
  }

  if(col){
    out.sort(function(a,b){
      var x=col.sv(a),y=col.sv(b);
      return (x>y?1:x<y?-1:0)*SORT.dir;
    });
  }else{
    out.sort(function(a,b){
      return D(b.reqDT)-D(a.reqDT);
    });
  }

  return out;
}

/* Export fetching is intentionally independent of Rows / Page.
   It scans every ERPNext record that belongs to the selected period/type,
   then applies the same branch/status/stage/requester/approver/search/age filters. */
async function fetchAllNonStockRowsForExport(type){
  var out=[],offset=0,chunk=250;

  while(true){
    var raw=await fetchRawPage(type,offset,chunk);
    if(!raw.length)break;

    var norm=await normalizeRaw(type,raw);

    norm.forEach(function(r){
      if(rowMatchesClientFilters(r))out.push(r);
    });

    offset+=raw.length;

    if(raw.length<chunk)break;
  }

  return out;
}

async function fetchAllStockSourceRowsForExport(kind){
  var out=[],offset=0,chunk=250;

  while(true){
    var raw=await fetchStockSourceRaw(kind,offset,chunk);
    if(!raw.length)break;

    var norm=await normalizeStockSource(kind,raw);

    norm.forEach(function(r){
      if(rowMatchesClientFilters(r))out.push(r);
    });

    offset+=raw.length;

    if(raw.length<chunk)break;
  }

  return out;
}

async function fetchAllStockRowsForExport(type){
  if(!canAccessReportType(type))return [];
  var kinds=activeStockSourceOrder(type);

  var batches=await Promise.all(
    kinds.map(function(k){
      return fetchAllStockSourceRowsForExport(k);
    })
  );

  var merged=[];

  batches.forEach(function(a){
    merged=merged.concat(a);
  });

  merged.sort(function(a,b){
    return D(b.reqDT)-D(a.reqDT);
  });

  return merged;
}

async function fetchAllRowsForExport(){
  var list=[];

  if(TYPE==='ALL'){

    var batches=await Promise.all(
      visibleTypeOrder().map(function(t){
        return isStockReportType(t)
          ? fetchAllStockRowsForExport(t)
          : fetchAllNonStockRowsForExport(t);
      })
    );

    batches.forEach(function(a){
      list=list.concat(a);
    });

  }else if(isStockReportType(TYPE)){

    if(!canAccessReportType(TYPE))return [];
    list=await fetchAllStockRowsForExport(TYPE);

  }else{

    list=await fetchAllNonStockRowsForExport(TYPE);

  }

  list=sortRowsForExport(list);

    // Export serial numbers must be independent of screen pagination.
    list.forEach(function(r,i){
      r.no=i+1;
    });

    return list;
}

function flat(list){
  var C=COLS(TYPE), fields=[];

  C.forEach(function(c){
    (c.x||[]).forEach(function(x){
      fields.push({h:x.h,v:x.v});
    });
  });

  list=(list||rows()).slice();

  return {
    heads:fields.map(function(f){return f.h}),
    body:list.map(function(r){
      return fields.map(function(f){
        var value=f.v(r);

        // CSV / Excel mobile or phone fields are ALWAYS masked,
        // regardless of the user's current Unmask No. state.
        if(/mobile/i.test(f.h)||/phone/i.test(f.h)){
          return maskedMobileForOutput(value);
        }

        return value;
      });
    }),
    n:list.length
  };
}

function dl(name,mime,content){
