    var allRows=await fetchAllRowsForExport();
    var f=flat(allRows), lines=[f.heads.map(q).join(',')];

    f.body.forEach(function(row){
      lines.push(row.map(q).join(','));
    });

    dl(
      exportStamp()+'.csv',
      'text/csv;charset=utf-8;',
      lines.join('\r\n')
