  L.push(['Branch',r.branch]);L.push([r.type==='STK'?'Stock Document':'Client',r.type==='STK'?(stockSourceLabel(r)+' · '+r.reqId):r.client.name]);
  if(r.type!=='STK'){L.push(['Mobile',maskedMobileForOutput(r.client.mobile)]);L.push(['Gender',r.client.gender]);L.push(['Age',r.client.age]);L.push(['Client Code',r.client.code])}
  L.push(['Booked / Raised By',r.bookedBy]);L.push(['Requested By',r.reqBy+(r.reqByDesig?' ('+r.reqByDesig+')':'')]);
  L.push(['Request Date & Time',fmtDT(r.reqDT)]);L.push(['Request Details',detTop(r)]);
  L.push(['Value',r.value]);L.push(['Credit / Discount',r.credit||0]);
