    L.push(['Level '+i+' Time Taken',s&&s.at?ageTxt(prevAt(r,i),s.at):'']);L.push(['Level '+i+' Remarks',s&&s.status!=='Pending'?s.remark:''])}
  L.push(['Total Turnaround',ageTxt(r.reqDT,doneAt(r)||TODAY)]);
  dl(r.reqId+'.csv','text/csv;charset=utf-8;',L.map(function(x){return x.map(q).join(',')}).join('\r\n'));
