function printRecord(){
  if(!CUR_REC)return;

  var w=window.open('','_blank');
  if(!w){
    toast('Pop-up blocked. Please allow pop-ups to print this request.','err');
    return;
  }

  // Build the printable request in strict privacy mode. The full mobile number
  // is not included in the generated print HTML, even when screen Unmask is ON.
  var previousOutputPrivacy=OUTPUT_PRIVACY_MODE;
  var recordHTML='';

  try{
    OUTPUT_PRIVACY_MODE=true;
    recordHTML=recHTML(CUR_REC);
  }finally{
    OUTPUT_PRIVACY_MODE=previousOutputPrivacy;
  }

  var title=TYPES[CUR_REC.type].name.toUpperCase()+' APPROVAL — '+CUR_REC.reqId;
  var html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+
    '<title>'+esc(title)+'</title><style>'+lifeRequestPrintCSS()+'</style></head><body><div class="life-print-page">'+
    '<div class="prnhead"><div class="brand"><b>LIFE SLIMMING &amp; COSMETIC CLINIC PVT. LTD.</b><span>APPROVAL REQUEST DETAIL</span></div>'+ 
    '<div class="print-meta"><b>'+esc(TYPES[CUR_REC.type].name)+' Approval</b>'+esc(CUR_REC.reqId)+'<br>Printed '+fmtDT(TODAY)+'</div></div>'+ 
    recordHTML+'</div></body></html>';

  w.document.open();
  w.document.write(html);
  w.document.close();
  w.focus();
  setTimeout(function(){w.print();},350);
}

