(async function init(){
  showLoad(true,'Loading approvals…','Reading your ERPNext access and first report page');
  try{
    await loadContext();
    // Configure mobile-number access after logged-in roles are known
    updateMobileMaskAccess();
    ensureLifeApprovalActionStyles();
    lifeInstallStatsCollapse();
    lifeInstallTableHoverScroll();
    // Ensure invoice links are white from the first modal render, before any click.
    ensureLifeInvoiceViewerStyles();

    // Browser Ctrl+P / menu Print also uses the same privacy rule.
    window.addEventListener('beforeprint',prepareReportPrintPrivacy);
    window.addEventListener('afterprint',restoreReportPrintPrivacy);

    byId('f-branch').innerHTML='<option value="">'+(BRANCH_FILTER_ACTIVE?'All Permitted Branches':'All Branches')+'</option>'+BRANCHES.map(function(b){return '<option>'+esc(b)+'</option>'}).join('');
    byId('f-req').innerHTML='<option value="">All Requesters</option>';
    byId('f-apr').innerHTML='<option value="">All Approvers</option>';
