    document.querySelectorAll('[data-a]').forEach(function(c){c.onclick=function(){document.querySelectorAll('[data-a]').forEach(function(x){x.classList.remove('on')});c.classList.add('on');F.age=c.dataset.a;PAGE=1;refreshReport()}});
    ['f-branch','f-status','f-stage','f-req','f-apr','f-rows'].forEach(function(i){byId(i).onchange=applyF});
